output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_entering_single_file_with_cart",
    "text": "Agents may not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "moveAction"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_cart_at_narrow_aisle_mouth",
    "text": "When arriving with a cart at the mouth of a single-file shelf aisle, the agent is obliged to park the cart there before proceeding.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "narrowAisleMouth",
          "hasCart"
        ]
      },
      "discharge": "parkCartAtMouth"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "A cart parked at the mouth of a single-file aisle must be retrieved before leaving the store.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrievedAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkedAtMouth",
      "discharge": "cartRetrievedAtMouth"
    }
  },
  {
    "id": "no_cartless_travel_in_wide_aisles",
    "text": "Except for entering a single-file aisle from its mouth, agents should not walk around cartless in wide aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": "moveAction",
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "moveAction",
          {
            "not": "hasCart"
          },
          "wideAisle",
          {
            "not": "narrowAisleMouth"
          },
          {
            "not": "enterSingleFileAisle"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_single_file_entry_requires_item_interaction",
    "text": "If an agent enters a single-file shelf aisle without a cart, they are obliged to perform a shelf interaction there.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        }
      },
      "events": {
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "moveAction"
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "cartlessShelfInteractionInSingleFile": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileWithoutCart",
      "discharge": "cartlessShelfInteractionInSingleFile"
    }
  },
  {
    "id": "cart_required_for_wide_shelf_interactions",
    "text": "Shelf interactions outside single-file shelf aisles must be performed while holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "wideShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wideShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "north_without_cart_only_for_single_file_access",
    "text": "Moving north without a cart is allowed only when already in a single-file shelf aisle or when entering one.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileNorthbound": {
          "pre": "N",
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "N",
          {
            "not": "hasCart"
          },
          {
            "not": "singleFileShelfAisle"
          },
          {
            "not": "enterSingleFileNorthbound"
          }
        ]
      }
    }
  }
]
